tasks.setup:
// lanes = how many float32 fit in the vector register
function lanes(registerBits) { return registerBits / 32; }
// theoretical speedup ceiling of a contiguous SoA loop = lane count
for (const [isa, bits] of [['SSE',128],['AVX2',256],['AVX-512',512],['NEON',128]]) {
  const n = lanes(bits);
  console.log(isa + ': ' + n + ' floats/instruction, ceiling ' + n + 'x vs scalar');
}
// AoS blocks this: gather costs ~10x a contiguous load, so the SoA loop is the only way to reach the ceiling.
console.log('AoS gather penalty: ~10x a contiguous load -> ceiling unreachable');

